(hn : 0 < n) (x : Fin n → ℝ) {a b : ℝ}
   (h : a < 1 ∨ b < 1) :
   let D : Set (ℝ × ℝ) := {p | p.1 < p.2 ∧ ∀ i, x i ∈ Ioo p.1 p.2}
   let L : ℝ × ℝ → ℝ := fun p ↦ NonstandardBeta.logLik x p.1 p.2 (b, a)
   ¬ BddAbove (L '' D)

(hn : 0 < n) (x : Fin n → ℝ) {a b : ℝ}
   (h : a < 1 ∨ b < 1) :
   let D : Set (ℝ × ℝ) := {p | p.1 < p.2 ∧ ∀ i, x i ∈ Ioo p.1 p.2}
